package fr.gemsofrod.encyclopedie.data

/** Traducciones españolas del nombre, los textos descriptivos y el interés joyero de las conchas marinas. */
object CoquillageTranslationsEs {
    val data: Map<String, CoquillageTranslation> = mapOf(
        "coquillage-ormeau" to CoquillageTranslation(
            nom = "Oreja de mar",
            descriptionCourte = "La concha de un gran gasterópodo marino, tapizada de un nácar de reflejos cambiantes muy apreciado en joyería.",
