        ),
        "coquillage-nautile" to CoquillageTranslation(
            nom = "Nautilo",
            descriptionCourte = "Cefalópodo de concha externa en espiral logarítmica, único superviviente actual de un grupo antaño dominado por los ammonites extintos.",
            descriptionLongue = "Último representante vivo de un orden de cefalópodos de concha externa que antaño contaba a los ammonites entre sus parientes, el nautilo habita las aguas profundas de los arrecifes indopacíficos y sube de noche a alimentarse. Serrada transversalmente, su concha revela una sucesión de cámaras tabicadas organizadas según una espiral logarítmica casi perfecta, a menudo citada como ejemplo de proporción natural notable. La pesca de la especie está hoy regulada por la CITES debido al declive de sus poblaciones.",
            interetJoaillerie = "Muy bueno: cortes pulidos enmarcados, colgantes, iluminación decorativa"
        )
